package org.apache.commons.lang.time;

import junit.framework.TestCase;
import java.util.Calendar;
import java.util.Date;

public class AgentBRT_Lang_65_raw_diff_Test extends TestCase {

    public void testReproduceBug() {
        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.JANUARY, 1, 10, 30, 45);
        calendar.set(Calendar.MILLISECOND, 123);

        Date expectedDate = calendar.getTime();

        // Attempt to truncate the date to MILLISECOND
        Date truncatedDate = DateUtils.truncate(expectedDate, Calendar.MILLISECOND);

        // Debug output to understand the behavior
        System.out.println("Expected: " + expectedDate.getTime() + ", Truncated: " + truncatedDate.getTime());

        // In the buggy version, this will fail because the date will be modified
        assertEquals("The date should not be modified when truncating to MILLISECOND.", expectedDate, truncatedDate);
    }
}

