package org.apache.commons.lang.time;

import org.junit.Test;
import org.junit.Assert;
import java.util.Calendar;

public class AgentBRT_Lang_65_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.JANUARY, 1, 10, 30, 45);
        calendar.set(Calendar.MILLISECOND, 123);

        Calendar expected = (Calendar) calendar.clone();

        // Attempt to modify the calendar by truncating to MILLISECOND
        DateUtils.modify(calendar, Calendar.MILLISECOND, false);

        // In the buggy version, this will fail because the calendar will be modified
        Assert.assertEquals("The calendar should not be modified when truncating to MILLISECOND.", expected, calendar);
    }
}

